const TITLES = {changes:'Changes',spec:'Modify specifications'};
const DESCRIPTIONS = {changes:'A focused brief for the next coding pass. Write it exactly how you want.',spec:'Add, change or remove requirements in TASK.md, then send those changes to the coder to apply to the shader.'};
const escapeHTML = text => String(text).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const slug = text => text.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const dateLabel = value => new Date(value).toLocaleString('en-AU',{day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit'});
function storageGet(key){try{return JSON.parse(localStorage.getItem(key));}catch{return null;}}
function storageSet(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('Browser draft storage is unavailable. Save to project to keep your work.',true);}}
function storageRemove(key){try{localStorage.removeItem(key);}catch{}}
function draftKey(id){return `stratus-studio:${state.workspace.project}:${id}`;}
function toast(message,error=false){clearTimeout(state.toastTimer);$('#toast').textContent=message;$('#toast').classList.toggle('error',error);$('#toast').hidden=false;state.toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-Studio-Token':state.workspace?.token??'',...options.headers}});let data;try{data=await response.json();}catch{throw new Error('The local server returned an unexpected response.');}if(!response.ok){const error=new Error(data.error||'Request failed');error.status=response.status;error.data=data;throw error;}return data;}
