async function save(){const doc=state.docs[state.current];if(!doc)return false;if(!dirty(doc)&&!doc.external){toast('Already saved.');return true;}return saveDocument(doc,{interactive:true});}
function setMode(mode){state.mode=mode;$('#editor-panes').className=`editor-panes mode-${mode}`;$$('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));storageSet('stratus-studio-pro-view',mode);updateLines();}
function insertText(before,after='',placeholder='text'){const area=editorArea();const start=area.selectionStart,end=area.selectionEnd,selected=area.value.slice(start,end)||placeholder;edit(area.value.slice(0,start)+before+selected+after+area.value.slice(end),{discrete:true});area.focus();area.setSelectionRange(start+before.length,start+before.length+selected.length);cursor();}
