function updateMatches(){const term=$('#find').value;const text=state.docs[state.current]?.text??'';let count=0,pos=0;if(term)while((pos=text.toLowerCase().indexOf(term.toLowerCase(),pos))!==-1){count++;pos+=Math.max(1,term.length);}$('#match-count').textContent=`${count} match${count===1?'':'es'}`;return count;}
function findNext(){const area=editorArea(),term=$('#find').value;if(!term)return;let index=area.value.toLowerCase().indexOf(term.toLowerCase(),area.selectionEnd);if(index===-1)index=area.value.toLowerCase().indexOf(term.toLowerCase());if(index===-1){toast('No matches found.');return;}area.focus();area.setSelectionRange(index,index+term.length);const line=area.value.slice(0,index).split('\n').length;area.scrollTop=Math.max(0,(line-3)*parseFloat(editorLineHeight()));cursor();}
function replaceOne(){const area=editorArea(),term=$('#find').value;if(!term)return;if(area.value.slice(area.selectionStart,area.selectionEnd).toLowerCase()!==term.toLowerCase()){findNext();return;}const start=area.selectionStart;edit(area.value.slice(0,start)+$('#replace').value+area.value.slice(area.selectionEnd),{discrete:true});area.setSelectionRange(start,start+$('#replace').value.length);findNext();}
function replaceAll(){const term=$('#find').value;if(!term)return;const doc=state.docs[state.current];const pattern=new RegExp(term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi');const count=updateMatches();edit(doc.text.replace(pattern,()=>$('#replace').value),{discrete:true});toast(`Replaced ${count} match${count===1?'':'es'}.`);}
function modal(title,content,actions=[],eyebrow='STRATUS STUDIO'){const box=$('#modal');box.classList.remove('image-modal');$('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-content').replaceChildren();if(typeof content==='string')$('#modal-content').innerHTML=content;else $('#modal-content').append(content);$('#modal-actions').className='modal-actions';$('#modal-actions').replaceChildren(...actions.map(({label,action,primary})=>{const b=document.createElement('button');b.className=`button ${primary?'primary':'subtle'}`;b.textContent=label;b.onclick=action;return b;}));if(!box.open)box.showModal();}
function closeModal(){$('#modal').close();state.modalKey=null;}
function diffMarkup(a,b){const left=a.split('\n'),right=b.split('\n');const leftSet=new Set(left),rightSet=new Set(right);return {left:left.map(l=>`<span${rightSet.has(l)?'':' class="removed"'}>${escapeHTML(l)||' '}</span>`).join('\n'),right:right.map(l=>`<span${leftSet.has(l)?'':' class="added"'}>${escapeHTML(l)||' '}</span>`).join('\n')};}
function showConflict(doc){const diff=diffMarkup(doc.text,doc.external.text);modal('This file changed elsewhere.',`<p class="modal-copy">Your draft is still here. Review the latest project version, then choose which text to keep editing. Nothing is overwritten until you save.</p><div class="conflict-columns"><div><h3>Your current draft</h3><pre>${diff.left}</pre></div><div><h3>Latest project file</h3><pre>${diff.right}</pre></div></div>`,[{label:'Keep editing my draft',action:()=>{const current=doc.external;doc.savedText=current.text;doc.revision=current.revision;doc.external=null;persistDraft(doc);closeModal();renderEditor();toast('Latest file recorded as the base. Review your draft, then Save.');}},{label:'Use project version',action:()=>{const current=doc.external;edit(current.text,{discrete:true});doc.savedText=current.text;doc.revision=current.revision;doc.external=null;persistDraft(doc);closeModal();renderEditor();toast('Project version loaded. Undo is available for your previous draft.');},primary:true}],doc.filename);}
async function history(){const key=state.current;state.modalKey=key;modal('Revision history','<p class="modal-copy">Loading saved versions…</p>',[],state.docs[key].filename);try{const data=await api(`/api/history/${key}`);const list=document.createElement('ul');list.className='revision-list';if(!data.entries.length){modal('A fresh start.','<p class="modal-copy">Each time you save a changed document, its previous version is backed up here. Your first save creates the first revision.</p>',[],state.docs[key].filename);return;}for(const row of data.entries){const li=document.createElement('li'),description=document.createElement('div');description.textContent=dateLabel(row.modified);const small=document.createElement('small');small.textContent=`${(row.bytes/1024).toFixed(1)} KB · Before a project save`;description.append(small);const view=document.createElement('button');view.className='button subtle';view.textContent='View revision';view.onclick=async()=>{try{const item=await api(`/api/history/${key}/${row.name}`);const wrap=document.createElement('div'),note=document.createElement('p'),pre=document.createElement('pre');note.className='modal-copy';note.textContent='Load this version into the editor as a draft. Save to project when you’re ready.';pre.className='revision-preview';pre.textContent=item.text;wrap.append(note,pre);modal(dateLabel(row.modified),wrap,[{label:'Back to history',action:history},{label:'Load as draft',primary:true,action:()=>{if(state.current!==key){location.hash='#'+key;loadDoc(key);}edit(item.text,{discrete:true});closeModal();toast('Revision loaded as a draft. Save when ready.');}}],state.docs[key].filename);}catch(e){toast(e.message,true);}};li.append(description,view);list.append(li);}modal('Revision history',list,[],state.docs[key].filename);}catch(e){modal('History unavailable',`<p class="modal-copy">${escapeHTML(e.message)}</p>`);}}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Coding brief copied. Paste it into your coding chat.');}catch{const area=document.createElement('textarea');area.className='modal-textarea';area.value=text;area.readOnly=true;modal('Your coding brief',area,[{label:'Close',action:closeModal,primary:true}]);area.select();}}
function copyBrief(){if(Object.values(state.docs).some(dirty)){toast('Save your edits first so the coding brief matches the project files.',true);return;}const folder=state.workspace.project+'/work/Custom instructions';copyText(`Apply the pending changes in "${folder}/CHANGES.md". Read "${folder}/TASK.md" as the complete shader target and follow the project AGENTS.md. Implement only pending requests; preserve unchanged visuals, controls and saved preferences. Verify the result, record evidence in CHANGE-LOG.md, and reconcile TASK.md with approved completed changes. Keep incomplete or unverified items pending. If there are no pending requests, report that there is no new shader work.`);}
async function chatDialog(preferredAction){
 const descriptions={run_both:'Save both editors, then run pending CHANGES.md requests and review the full TASK.md target for unfinished requirements. This can be a larger coding pass. Preserve completed work and keep unverified items pending.',related:'Send a specific Stratus shader request directly to this coding chat. Describe the work and any relevant project files. Other pending requests are not started automatically.',stage_run:'Save all editor changes, then send the TASK.md additions, edits and removals plus pending CHANGES.md requests to Coding Stratus (2) to stage and run. Sending stops if a save fails or a conflict needs resolving.',stage:'Review and refine CHANGES.md for the next coding pass. This stages the brief without starting shader implementation.',run:'Request implementation of pending CHANGES.md items. Preserve the full TASK.md target, reconcile it after completed changes, and record evidence in CHANGE-LOG.md.',spec:'Edit TASK.md: the complete shader target and clean-rebuild specification, including design, behaviour, construction and checks. This edits the target without starting shader implementation.'};
 modal('Coding Stratus (2)',`<div class="chat-form"><p class="modal-copy">TASK.md is the full shader target. CHANGES.md holds the next relevant work. Saving alone never starts a task.</p><label for="chat-action">Action</label><select id="chat-action"><option value="stage_run">Stage and send for running</option><option value="stage">Stage changes</option><option value="run">Run pending changes</option><option value="run_both">Run Changes + TASK.md</option><option value="spec">Modify TASK.md</option><option value="related">Related shader work</option></select><p id="chat-description" class="modal-copy"></p><label for="chat-instructions">Instructions <span id="chat-optional">(optional)</span></label><textarea id="chat-instructions" maxlength="12000" rows="5" placeholder="Describe the result you want…"></textarea><p id="chat-result" role="status" aria-live="polite"></p><details><summary>Recent delivery receipts</summary><div id="chat-receipts">Loading…</div></details></div>`,[{label:'Close',action:closeModal},{label:'Send to chat',primary:true,action:sendChat}], 'PROJECT CHAT');
 const draft=storageGet('stratus-chat-draft')||{};
 $('#chat-action').value=(typeof preferredAction==='string'?preferredAction:null)||draft.operation|| (state.current==='spec'?'spec':'stage');$('#chat-instructions').value=draft.instructions||'';
 const update=()=>{const action=$('#chat-action').value;$('#chat-description').textContent=descriptions[action];$('#chat-optional').textContent=['spec','related'].includes(action)?'(required)':'(optional)';$('#chat-instructions').required=['spec','related'].includes(action);$('#modal-actions button:last-child').textContent=action==='stage_run'?'Stage and send for running':action==='run_both'?'Run Changes + TASK.md':action==='run'?'Run pending changes':action==='spec'?'Send TASK.md edit':action==='related'?'Send related work':'Stage changes';storageSet('stratus-chat-draft',{operation:action,instructions:$('#chat-instructions').value});};
 $('#chat-action').onchange=update;$('#chat-instructions').oninput=update;update();
 await chatReceipts();
}
async function chatReceipts(){try{const data=await api('/api/chat');if(!$('#chat-receipts'))return;$('#chat-receipts').replaceChildren();for(const item of data.requests){const row=document.createElement('p');row.textContent=`${dateLabel(item.created)} · ${item.operation} · ${item.status}${item.queueId?' · '+item.queueId:''}`;$('#chat-receipts').append(row);}if(!data.requests.length)$('#chat-receipts').textContent='No requests sent from Studio yet.';if(!data.available)$('#chat-result').textContent='Codex CLI is unavailable. Open the Codex app and restart Studio.';}catch(e){if($('#chat-receipts'))$('#chat-receipts').textContent=e.message;}}
async function sendChat(){
 const result=$('#chat-result'),button=$('#modal-actions button:last-child');
 if(state.sending){result.textContent='A save and send request is already in progress.';return;}
 const operation=$('#chat-action').value,instructions=$('#chat-instructions').value.trim();
 if(['spec','related'].includes(operation)&&!instructions){result.textContent='Describe the specification edit or related shader work you want.';$('#chat-instructions').focus();return;}
 if(!['stage_run','run_both'].includes(operation)&&Object.values(state.docs).some(doc=>dirty(doc)||doc.external||doc.draft)){result.textContent='Save or resolve your drafts and external changes before sending.';return;}
 state.sending=true;button.disabled=true;$('#chat-action').disabled=true;$('#chat-instructions').disabled=true;
 const live=()=>$('#chat-result')===result;
 const progress=message=>{if(live())result.textContent=message;};
 let submitted=false,keepDisabled=false;
 try{
  if(['stage_run','run_both'].includes(operation)){
   clearTimeout(state.autoTimer);
   while(saveFlight){try{await saveFlight;}catch{}}
   for(const doc of Object.values(state.docs)){if(doc.draft)throw new Error(`Recover or dismiss the stored draft for ${doc.filename} before sending.`);if(doc.external)throw new Error(`Resolve the external changes in ${doc.filename} before sending.`);}
   const snapshots=Object.fromEntries(Object.values(state.docs).map(doc=>[doc.id,doc.text]));
   for(const doc of Object.values(state.docs)){if(dirty(doc)){progress(`Saving ${doc.filename}…`);await saveDocument(doc);}}
   if(Object.values(state.docs).some(doc=>dirty(doc)||doc.external||doc.draft||doc.text!==snapshots[doc.id]))throw new Error('Edits changed while saving. Your work is preserved; review it and send again.');
  }
  progress('All edits saved. Sending to Coding Stratus (2)…');
  const request={id:crypto.randomUUID(),operation,instructions,revisions:Object.fromEntries(Object.entries(state.docs).map(([id,doc])=>[id,doc.revision]))};
  submitted=true;keepDisabled=true;
  const receipt=await api('/api/chat',{method:'POST',body:JSON.stringify(request)});
  progress(receipt.status==='queued'?`Saved and queued in Coding Stratus (2). Open that chat for progress and results. Receipt: ${receipt.queueId}`:receipt.detail);
  if(live())await chatReceipts();
  if(receipt.status==='queued'||receipt.status==='waiting'){
   const draft=storageGet('stratus-chat-draft');if(draft?.operation===operation&&draft?.instructions?.trim()===instructions)storageRemove('stratus-chat-draft');
   toast(receipt.status==='waiting'?'Saved and added to the cloud queue.':'Saved and queued in Coding Stratus (2).');
  }else if(receipt.status==='failed')keepDisabled=false;
 }catch(error){
  progress(!submitted?`Not sent. ${error.message}`:error.status?error.message:'Delivery could not be confirmed. Check Coding Stratus (2) and recent receipts before sending again.');
  if(!submitted||error.status)keepDisabled=false;
 }finally{
  state.sending=false;
  if(live()&&!keepDisabled){button.disabled=false;$('#chat-action').disabled=false;$('#chat-instructions').disabled=false;}
 }
}
function recoverDraft(){const doc=state.docs[state.current];if(!doc.draft)return;const draft=doc.draft;doc.draft=null;edit(draft.text,{discrete:true});if(draft.revision!==doc.revision){doc.external={...doc,text:doc.savedText};doc.revision=draft.revision;showConflict(doc);}renderEditor();toast('Browser draft recovered.');}
async function showActivity(){try{const data=await api('/api/activity');$('#activity-content').innerHTML=markdown(data.text);$('#activity-outline').replaceChildren(...headings(data.text).filter(h=>h.level===2).map(h=>{const b=document.createElement('button');b.textContent=h.text;b.onclick=()=>$('#activity-content').querySelector(`#${CSS.escape(h.id)}`)?.scrollIntoView({behavior:'smooth',block:'start'});return b;}));}catch(e){$('#activity-content').textContent=e.message;}}
function route(){if(!state.workspace)return;const id=location.hash.slice(1)||'home';const view=['home','changes','spec','activity'].includes(id)?id:'home';if(state.current)persistDraft(state.docs[state.current]);$('#home-view').hidden=view!=='home';$('#editor-view').hidden=!['changes','spec'].includes(view);$('#activity-view').hidden=view!=='activity';document.title=`${view==='home'?'Overview':view==='activity'?'Build notes':TITLES[view]} — Stratus Studio`;$$('[data-nav]').forEach(link=>{link.classList.toggle('active',link.dataset.nav===view);if(link.dataset.nav===view)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});document.body.classList.toggle('focus-mode',['changes','spec'].includes(view));if(['changes','spec'].includes(view))loadDoc(view);else{if(view==='activity')showActivity();}window.scrollTo(0,0);}
async function poll(){if(!state.workspace||state.pollBusy||state.saving||state.sending||document.hidden)return;state.pollBusy=true;try{const data=await api('/api/workspace');state.workspace.token=data.token;connection(true);for(const [id,fresh] of Object.entries(data.documents)){const doc=state.docs[id];if(fresh.revision!==doc.revision){if(dirty(doc)){doc.external=fresh;}else{doc.text=fresh.text;doc.savedText=fresh.text;doc.revision=fresh.revision;doc.modified=fresh.modified;if(state.current===id)editorArea().value=fresh.text;}}}state.workspace.release=data.release;updateHome();if(state.current)renderEditor();}catch{connection(false);}finally{state.pollBusy=false;}}
function wire(){
 editorArea().addEventListener('input',e=>edit(e.target.value));editorArea().addEventListener('click',cursor);editorArea().addEventListener('keyup',cursor);editorArea().addEventListener('select',cursor);editorArea().addEventListener('scroll',()=>$('#line-numbers').scrollTop=editorArea().scrollTop);
 $('#save').onclick=save;$('#focus-save').onclick=save;$('#focus-history').onclick=history;$('#focus-copy').onclick=copyBrief;$('#undo').onclick=()=>undo();$('#redo').onclick=()=>undo(true);$$('[data-format]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>format(b.dataset.format);});$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#history').onclick=history;$('#sidebar-help').addEventListener('click',e=>{const b=e.target.closest('[data-insert]');if(b)addBlock(b.dataset.insert);});$('#copy-brief').onclick=copyBrief;$('#home-copy').onclick=chatDialog;$('#chat-connect').onclick=chatDialog;$('#stage-send').onclick=()=>chatDialog('stage_run');
 $('#preview').addEventListener('change',e=>{if(e.target.matches('[data-task-line]')){const doc=state.docs[state.current];const lines=doc.text.split('\n');const line=Number(e.target.dataset.taskLine);lines[line]=lines[line].replace(/\[([ xX])\]/,e.target.checked?'[x]':'[ ]');edit(lines.join('\n'),{discrete:true});}});
 $('#search-toggle').onclick=()=>{if(codeEditor){codeEditor.focus();codeEditor.trigger('studio','editor.action.startFindReplaceAction',null);return;}$('#search-panel').hidden=!$('#search-panel').hidden;if(!$('#search-panel').hidden)$('#find').focus();};$('#search-close').onclick=()=>$('#search-panel').hidden=true;$('#find').oninput=updateMatches;$('#find').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();findNext();}};$('#find-next').onclick=findNext;$('#replace-one').onclick=replaceOne;$('#replace-all').onclick=replaceAll;
 $('#editor-options').onclick=()=>$('#preferences').hidden=!$('#preferences').hidden;const preferences=storageGet('stratus-studio-preferences')||{};$('#font-size').value=preferences.fontSize||'14';$('#wrap').checked=preferences.wrap!==false;$('#autosave').checked=preferences.autosave===true;function applyPreferences(){if(codeEditor)codeEditor.updateOptions({fontSize:Number($('#font-size').value),wordWrap:$('#wrap').checked?'on':'off'});document.documentElement.style.setProperty('--editor-size',$('#font-size').value+'px');editorArea().classList.toggle('nowrap',!$('#wrap').checked);storageSet('stratus-studio-preferences',{fontSize:$('#font-size').value,wrap:$('#wrap').checked,autosave:$('#autosave').checked});updateLines();}['font-size','wrap','autosave'].forEach(id=>$('#'+id).onchange=applyPreferences);applyPreferences();$('#focus-toggle').onclick=()=>{document.body.classList.toggle('focus-mode');updateLines();};
 $('#export').onclick=()=>{const doc=state.docs[state.current];const blob=new Blob([doc.text],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=doc.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Markdown export downloaded.');};$('#import').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1_500_000){toast('Import a Markdown file smaller than 1.5 MB.',true);e.target.value='';return;}const text=await file.text();const key=state.current;modal('Import Markdown',`<p class="modal-copy">Load <strong>${escapeHTML(file.name)}</strong> into the ${TITLES[key].toLowerCase()} editor. This replaces your editor text as an unsaved draft; Undo remains available.</p>`,[{label:'Cancel',action:closeModal},{label:'Load as draft',primary:true,action:()=>{if(state.current!==key)loadDoc(key);edit(text,{discrete:true});closeModal();toast('Imported as a draft. Save to update the project.');}}]);e.target.value='';};
 $('#recover-draft').onclick=recoverDraft;$('#dismiss-draft').onclick=()=>{const doc=state.docs[state.current];doc.draft=null;storageRemove(draftKey(doc.id));renderEditor();};$('#review-external').onclick=()=>showConflict(state.docs[state.current]);$('#modal-close').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
 $$('.scene').forEach(b=>b.onclick=()=>{const names={river:'Water with depth.',sky:'A sky with character.',rain:'Weather you can feel.'};modal(names[b.dataset.image],`<img src="/assets/${b.dataset.image}.png" alt="Actual Stratus 1.6.7 Minecraft capture"><p class="modal-copy">Actual in-game capture from the Stratus 1.6.7 visual report. This is a saved reference, not a live render.</p>`,[],'STRATUS 1.6.7 / IN-GAME CAPTURE');$('#modal').classList.add('image-modal');});
 $$('[data-file]').forEach(button=>button.onclick=()=>{location.hash='#'+button.dataset.file;});$('#command-palette').onclick=()=>{if(codeEditor){codeEditor.focus();codeEditor.trigger('studio','editor.action.quickCommand',null);}else toast('The code editor is still loading.');};window.addEventListener('hashchange',route);window.addEventListener('beforeunload',e=>{for(const doc of Object.values(state.docs))persistDraft(doc);if(Object.values(state.docs).some(dirty)){e.preventDefault();e.returnValue='';}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
 document.addEventListener('keydown',e=>{const mod=e.metaKey||e.ctrlKey;const inEditor=!$('#editor-view').hidden;if(e.key==='Escape'){$('#preferences').hidden=true;$('#search-panel').hidden=true;updateLines();}if(mod&&e.key.toLowerCase()==='s'&&inEditor){e.preventDefault();save();}if(mod&&e.key.toLowerCase()==='f'&&inEditor&&!$('#modal').open){e.preventDefault();if(codeEditor){codeEditor.focus();codeEditor.trigger('studio','actions.find',null);}else{$('#search-panel').hidden=false;$('#find').focus();$('#find').select();}}if(!codeEditor&&document.activeElement===document.querySelector('#source')){if(mod&&e.key.toLowerCase()==='b'){e.preventDefault();format('bold');}if(mod&&e.key.toLowerCase()==='i'){e.preventDefault();format('italic');}if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();undo(true);}if(e.key==='Tab'){e.preventDefault();const area=editorArea(),start=area.selectionStart,end=area.selectionEnd;if(e.shiftKey||area.value.slice(start,end).includes('\n')){const lineStart=area.value.lastIndexOf('\n',start-1)+1;const text=area.value.slice(lineStart,end);const replacement=text.split('\n').map(line=>e.shiftKey?line.replace(/^( {1,2}|\t)/,''):'  '+line).join('\n');edit(area.value.slice(0,lineStart)+replacement+area.value.slice(end),{discrete:true});area.setSelectionRange(lineStart,lineStart+replacement.length);}else{edit(area.value.slice(0,start)+'  '+area.value.slice(end),{discrete:true});area.setSelectionRange(start+2,start+2);}}}});
 new ResizeObserver(updateLines).observe($('#editor-panes'));setMode(storageGet('stratus-studio-pro-view')||'write');
}
async function boot(){try{state.workspace=await api('/api/workspace');state.docs=Object.fromEntries(Object.entries(state.workspace.documents).map(([key,raw])=>[key,initialiseDoc(raw)]));for(const doc of Object.values(state.docs)){const draft=storageGet(draftKey(doc.id));if(draft?.text!==undefined&&draft.text!==doc.text)doc.draft=draft;}wire();updateHome();connection(true);route();initialiseCodeEditor().catch(error=>{console.error('Editor startup failed',error);toast('Advanced editor unavailable. Plain Markdown editing remains available.',true);});setInterval(poll,10000);}catch(e){connection(false);$('#home-view').innerHTML='<div class="editor-heading"><div><p class="eyebrow">WORKSPACE CONNECTION</p><h1>Let’s reconnect.</h1><p>Start Stratus Studio with start.command, then reload this page.</p></div></div>';toast(e.message,true);}}
boot();
